# -*- coding: utf-8 -*-
"""
사업 설명 — **한국어는 사람이 쓴다.**

`scrape_desc.py` 가 나스닥·닛케이·stockanalysis 에서 원문을 받아 오지만 그건
영어·일본어다. 러너에는 번역기가 없으므로, 회사 한글명을 `companies*.py` 에
손으로 넣었듯 사업 설명도 여기에 손으로 넣는다.

**규칙**

- 한 줄. 눌렀을 때 "아, 이런 걸 파는 회사구나"가 바로 와야 한다.
- **무엇을 파는지 먼저.** 업종 이름("에너지", "산업재")은 아무것도 안 알려준다.
  「천연가스를 모아 파이프로 실어 나른다」가 「에너지」보다 백 배 낫다.
- 아는 것만 쓴다. 모르면 비워 둔다 — 그러면 화면이 원문을 그대로 보여준다.
- 광고문구를 옮기지 않는다. 회사 소개문은 자기 자랑이라 그대로 옮기면
  "미래를 여는 혁신 기업" 같은 말만 남는다.

열쇠는 `시장:코드` 다.
"""

